-- =====================================================================
-- 12 · GUION DE LA DINÁMICA 3 Y TABLA PRIVADA DE NOTAS (teleprompter)
-- 1) Pone en "marketing" los 27 conceptos tal como están en las notas
--    de Canva (diapositivas 14 y 15), solo si la lista sigue siendo la
--    provisional. Conserva los toques de conceptos que ya existían.
-- 2) Crea la tabla notas_canva: las notas originales de Canva por
--    diapositiva. Solo la ponente puede leerlas (nunca alumnos).
-- No borra nada. Se puede correr más de una vez.
-- =====================================================================
update public.actividades a
set config = a.config || jsonb_build_object('toques', true, 'provisional', false, 'conceptos', $json$[{"id": "g01", "nombre": "Hablar con proveedores", "clase": "operacion", "estado": "pendiente", "pagina": "PBL8JRx14QK8QbCY", "seccion": "Operar un negocio también consume tiempo"}, {"id": "g02", "nombre": "Coordinar entregas y rutas", "clase": "operacion", "estado": "pendiente", "pagina": "PBL8JRx14QK8QbCY", "seccion": "Operar un negocio también consume tiempo"}, {"id": "g03", "nombre": "Crear contenido constantemente", "clase": "improvisar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "El marketing nunca se detiene"}, {"id": "g04", "nombre": "Publicar cuando puedo", "clase": "improvisar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "El marketing nunca se detiene"}, {"id": "g05", "nombre": "Tener mi planeación de contenido", "clase": "planificar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "El marketing nunca se detiene"}, {"id": "g06", "nombre": "Organizar ideas de contenido por adelantado", "clase": "planificar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "El marketing nunca se detiene"}, {"id": "g07", "nombre": "Crear campañas de venta sobre la marcha", "clase": "improvisar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "El marketing nunca se detiene"}, {"id": "g08", "nombre": "Planear campañas de venta con anticipación", "clase": "planificar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "El marketing nunca se detiene"}, {"id": "g09", "nombre": "Crear contenido desde cero en ChatGPT", "clase": "improvisar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "Dejar de empezar desde cero"}, {"id": "g10", "nombre": "Volver a explicar el contexto de mi negocio", "clase": "improvisar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "Dejar de empezar desde cero"}, {"id": "g11", "nombre": "Utilizar la memoria de ChatGPT", "clase": "planificar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "Dejar de empezar desde cero"}, {"id": "g12", "nombre": "Tener instrucciones y contexto preparados", "clase": "planificar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "Dejar de empezar desde cero"}, {"id": "g13", "nombre": "Elegir qué producto promocionar sobre la marcha", "clase": "improvisar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "Dejar de empezar desde cero"}, {"id": "g14", "nombre": "Planear qué producto voy a promocionar", "clase": "planificar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "Dejar de empezar desde cero"}, {"id": "g15", "nombre": "Probar herramientas sin un objetivo claro", "clase": "improvisar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "Dejar de empezar desde cero"}, {"id": "g16", "nombre": "Elegir herramientas para optimizar procesos", "clase": "planificar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "Dejar de empezar desde cero"}, {"id": "g17", "nombre": "Contestar prospectos conforme van llegando", "clase": "improvisar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "Vender, responder, editar y medir"}, {"id": "g18", "nombre": "Improvisar respuestas de WhatsApp", "clase": "improvisar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "Vender, responder, editar y medir"}, {"id": "g19", "nombre": "Tener respuestas preparadas en WhatsApp", "clase": "planificar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "Vender, responder, editar y medir"}, {"id": "g20", "nombre": "Tener procesos de seguimiento a prospectos", "clase": "planificar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "Vender, responder, editar y medir"}, {"id": "g21", "nombre": "Editar videos desde cero", "clase": "improvisar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "Vender, responder, editar y medir"}, {"id": "g22", "nombre": "Utilizar plantillas con mis colores y formatos", "clase": "planificar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "Vender, responder, editar y medir"}, {"id": "g23", "nombre": "Tener recursos gráficos preparados", "clase": "planificar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "Vender, responder, editar y medir"}, {"id": "g24", "nombre": "Utilizar herramientas para agilizar la edición", "clase": "planificar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "Vender, responder, editar y medir"}, {"id": "g25", "nombre": "Decidir qué repetir por intuición", "clase": "improvisar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "Vender, responder, editar y medir"}, {"id": "g26", "nombre": "Medir resultados de publicaciones y campañas", "clase": "planificar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "Vender, responder, editar y medir"}, {"id": "g27", "nombre": "Ajustar mi estrategia con base en resultados", "clase": "planificar", "estado": "pendiente", "pagina": "PBvMq3yTcXlykvDL", "seccion": "Vender, responder, editar y medir"}]$json$::jsonb)
from public.talleres t
where t.id = a.taller_id and t.slug = 'primer-agente' and a.clave = 'marketing'
  and coalesce((a.config->>'provisional')::boolean, true);

create table if not exists public.notas_canva (
  taller_id  uuid not null references public.talleres(id) on delete cascade,
  n          int not null,
  page_id    text not null,
  notas      text,
  actualizado_en timestamptz not null default now(),
  primary key (taller_id, page_id)
);
alter table public.notas_canva enable row level security;
drop policy if exists p_notascanva_sel on public.notas_canva;
create policy p_notascanva_sel on public.notas_canva for select using (public.es_ponente(taller_id));
drop policy if exists p_notascanva_all on public.notas_canva;
create policy p_notascanva_all on public.notas_canva for all using (public.es_ponente(taller_id)) with check (public.es_ponente(taller_id));
